cat > settled.sh <<'EOF'
#!/bin/sh
# Copyright (c) 2026 Stewart Rogers. Apache License 2.0. See Book/LICENSE-CODE.txt.
# settled.sh LOG: waits until every exchange surl's log says was opened has ended, so the log holds the whole
# of each one. It gives up after 5 seconds, leaving the log as it is.
tries=0
while [ "$(grep -c ' opened: ' "$1")" -gt "$(grep -c ' ended; ' "$1")" ] && [ "$tries" -lt 25 ]; do
  sleep 0.2
  tries=$((tries + 1))
done
EOF
cat > who-stored.sh <<'EOF'
#!/bin/sh
# Copyright (c) 2026 Stewart Rogers. Apache License 2.0. See Book/LICENSE-CODE.txt.
# who-stored.sh LOG NAME: reads surl's verbose log and prints, for each upload of NAME the server completed,
# the exchange it came in on and the account logged in there, then the account that stored it last.
# An upload the server refused is left out. Exit 1 when the log shows no completed upload of NAME.
tr -d '\r' < "$1" | awk -v name="$2" '
  { n = substr($1, 2) }
  $2 == "*" && $3 == "Login" && $4 == "accepted:" { who[n] = $NF }
  $2 == "<" && $0 == "#" n " < STOR " name "\\r\\n" { asked[n] = 1 }
  $2 == ">" && asked[n] && $3 ~ /^[2-5][0-9][0-9]$/ {
    if ($3 ~ /^2/) { print "exchange " n ": " who[n] " stored " name; last = who[n] }
    asked[n] = 0
  }
  END {
    if (last == "") { print "no completed upload of " name " in the log"; exit 1 }
    print "last stored by " last
  }'
EOF
surl -v --log-file surl.log --user alice:north-7 --user bob:south-9 --allow-plaintext-auth --allow-uploads --max-filesize 100 --directory site ftp://127.0.0.1:8080/ &
surl --log-file quiet.log --user bob:south-9 --allow-plaintext-auth --allow-uploads ftp://127.0.0.1:8081/ &
surl --user bob:south-9 --allow-uploads ftp://127.0.0.1:8082/ &
sleep 1
sh settled.sh surl.log && sh who-stored.sh surl.log export.csv
kill $(jobs -p)
